import json


async def main(args: Args) -> Output:
    p = args.params or {}
    try:
        score = int(float(p.get('llm_match_score') or 0))
    except Exception:
        score = 0
    score = max(0, min(100, score))
    if score >= 80:
        level = '匹配度较高'
    elif score >= 60:
        level = '基本匹配'
    else:
        level = '匹配度偏低'

    def _load(key):
        raw = p.get(key)
        if isinstance(raw, list):
            return [x for x in raw if isinstance(x, dict)]
        if isinstance(raw, str) and raw.strip():
            try:
                data = json.loads(raw)
            except Exception:
                data = []
            if isinstance(data, list):
                return [x for x in data if isinstance(x, dict)]
        return []

    gap = _load('llm_gap_json')
    sug = _load('llm_suggest_json')
    summary_in = str(p.get('llm_summary') or '')
    sensitive_note = str(p.get('v_sensitive_note') or '')

    lines = ['匹配度：%d 分（%s）' % (score, level)]
    if summary_in:
        lines.append(summary_in)
    if gap:
        lines.append('能力缺口（按重要性排序）：')
        for i, g in enumerate(gap[:8]):
            lines.append('  %d) %s —— 补齐方式：%s' % (
                i + 1, str(g.get('gap') or ''), str(g.get('how') or '')))
    if sug:
        lines.append('简历修改建议（原文 → 建议改写）：')
        for i, s in enumerate(sug[:8]):
            lines.append('  %d) 「%s」→「%s」（理由：%s）' % (
                i + 1, str(s.get('origin') or ''), str(s.get('rewrite') or ''),
                str(s.get('why') or '')))
    if sensitive_note:
        lines.append(sensitive_note)

    ret: Output = {
        'v_score': score,
        'v_level': level,
        'v_gap': gap,
        'v_suggest': sug,
        'v_summary': '\n'.join(lines),
    }
    return ret
